1	// Every panel in the working dataset is named VESSEL_<prefix>_... and lives under
2	// references/<paper-slug>/figures/panels/. The px -> um scale is measured from the scale bar
3	// the figure prints and tabulated as SCALEBAR_PX in the extraction script, keyed by panel-name
4	// prefix (longest match wins) so one figure can calibrate rows that differ in zoom.
5	//
6	// A panel may instead carry its scale DIRECTLY, in UMPP_DIRECT, when the source image's own
7	// metadata states um/px and no bar is involved — stronger evidence than a measured bar.
8	//
9	// A panel whose scale genuinely cannot be measured — the figure draws no bar — is not a
10	// violation, but it must SAY so: an entry in UNCALIBRATED, carrying the reason. The point of
11	// this rule is that no panel is uncalibrated by accident.
12	const PANEL = /^references\/[^/]+\/figures\/panels\/VESSEL_(.+)\.png$/i;
13	const MEASURE = 'analysis/measure_vessels.py';
14	const TABLE = /SCALEBAR_PX\s*=\s*\{([\s\S]*?)\}/;
15	const DIRECT = /UMPP_DIRECT\s*=\s*\{([\s\S]*?)\n\}/;
16	const DECLARED = /UNCALIBRATED\s*=\s*\{([\s\S]*?)\n\}/;
17	
18	// The wang-2022 panels carry a channel suffix the calibration keys never include.
19	const stripSuffix = (s) => s.replace(/_gP-CD31_red$/, '');
20	
21	const keysOf = (block) => (block ? [...block.matchAll(/['"]([^'"]+)['"]\s*:/g)].map((m) => m[1]) : []);
22	
23	const rule = {
24	  id: 'panel-scale-calibration',
25	  severity: 'blocking',
26	  description: 'Every working panel is either scale-calibrated or declared uncalibrated',
27	  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
28	  why: 'an uncalibrated figure does not fail — it silently reports "um n/a" and drops out of every length and density number, so a panel added without its bar measurement quietly shrinks the result set',
29	
30	  run(ctx) {
31	    const text = ctx.read(MEASURE);
32	    if (text === null) return [];
33	    const lines = text.split('\n');
34	    const lineOf = (needle) => lines.findIndex((l) => l.includes(needle)) + 1 || null;
35	    const m = TABLE.exec(text);
36	    if (!m) {
37	      return [{
38	        rule: rule.id,
39	        severity: rule.severity,
40	        file: MEASURE,
41	        line: null,
42	        what: 'no SCALEBAR_PX table found',
43	        why: rule.why,
44	        fix: 'keep the per-prefix scale-bar widths in a SCALEBAR_PX = { ... } table in this file — it is the single calibration source annotate_overlays.py imports',
45	        doc: rule.doc,
46	      }];
47	    }
48	    const calibrated = keysOf(m[1]);
49	    const direct = keysOf(DIRECT.exec(text)?.[1]);
50	    const declared = keysOf(DECLARED.exec(text)?.[1]);
51	    const covers = (name) => [...calibrated, ...direct, ...declared].some((k) => name.startsWith(k));
52	
53	    const panels = new Set();
54	    for (const f of ctx.tracked) {
55	      const hit = PANEL.exec(f);
56	      if (hit) panels.add(stripSuffix(hit[1]));
57	    }
58	    return [...panels].sort()
59	      .filter((name) => !covers(name))
60	      .map((name) => ({
61	        rule: rule.id,
62	        severity: rule.severity,
63	        file: MEASURE,
64	        line: lineOf('SCALEBAR_PX'),
65	        what: `VESSEL_${name} matches no SCALEBAR_PX, UMPP_DIRECT or UNCALIBRATED prefix`,
66	        why: rule.why,
67	        fix: `measure the scale bar printed on that panel's row and add a '<prefix>': <bar width in px> entry to SCALEBAR_PX (plus SCALEBAR_UM if the bar is not 50 um); or, if the source image states its own um/px, put it in UMPP_DIRECT with its provenance; or, if the figure draws no bar at all, add the prefix to UNCALIBRATED with the reason`,
68	        doc: rule.doc,
69	      }));
70	  },
71	};
72	
73	export default rule;
