327	// --- render-outputs-gitignored ----------------------------------------------
328	
329	const script = (dir) => [
330	  '#!/usr/bin/env python3',
331	  '"""Writes PNGs to analysis/reports/ (gitignored)."""',
332	  'import os',
333	  'HERE = os.path.dirname(os.path.abspath(__file__))',
334	  `OUT = os.path.join(HERE, '${dir}')`,
335	  "SRC = os.path.normpath(os.path.join(HERE, '..', 'references'))",
336	  '',
337	  'def main():',
338	  '    os.makedirs(OUT, exist_ok=True)',
339	  "    canvas.save(os.path.join(OUT, name + '.png'))",
340	].join('\n');
341	
342	const GITIGNORE = ['# generated overlays', '/analysis/overlays/', '/analysis/annotated/', '__pycache__/'].join('\n');
343	
344	test('render-outputs-gitignored fires on a new output directory nobody ignored', () => {
345	  const findings = renderOutputsGitignored.run(ctx({
346	    files: { [ANNOTATE]: script('reports'), '.gitignore': GITIGNORE },
347	    tracked: [ANNOTATE, '.gitignore'],
348	  }));
349	  assert.equal(findings.length, 1);
350	  assert.equal(findings[0].file, ANNOTATE);
351	  assert.equal(findings[0].line, 9);
352	  assert.match(findings[0].what, /analysis\/reports\/, which no .gitignore entry covers/);
353	});
354	
355	test('render-outputs-gitignored fires when an entry is un-ignored by a later negation', () => {
356	  const findings = renderOutputsGitignored.run(ctx({
357	    files: {
358	      [ANNOTATE]: script('annotated'),
359	      '.gitignore': `${GITIGNORE}\n!/analysis/annotated/\n`,
360	    },
361	    tracked: [ANNOTATE, '.gitignore'],
362	  }));
363	  assert.equal(findings.length, 1);
364	  assert.match(findings[0].what, /analysis\/annotated\//);
365	});
366	
367	test('render-outputs-gitignored is quiet when every render directory is ignored', () => {
368	  const findings = renderOutputsGitignored.run(ctx({
369	    files: {
370	      [ANNOTATE]: script('annotated'),
371	      [MEASURE]: script('overlays'),
372	      '.gitignore': GITIGNORE,
373	      // A source tree the scripts only read from is not an output directory.
374	      'references/wang-2022-cd31-vascular-network/figures/panels/expected-results.md': '# expectations\n',
375	    },
376	    tracked: [ANNOTATE, MEASURE, '.gitignore', 'references/wang-2022-cd31-vascular-network/figures/panels/expected-results.md'],
377	  }));
378	  assert.deepEqual(findings, []);
379	});
380	
381	test('render-outputs-gitignored honours a .gitignore beside the scripts', () => {
382	  const findings = renderOutputsGitignored.run(ctx({
383	    files: {
384	      [ANNOTATE]: script('annotated'),
385	      '.gitignore': '__pycache__/\n',
386	      'analysis/.gitignore': 'annotated/\n',
387	    },
388	    tracked: [ANNOTATE, '.gitignore', 'analysis/.gitignore'],
389	  }));
390	  assert.deepEqual(findings, []);
391	});
392	
393	let failed = 0;
394	for (const [name, fn] of cases) {
395	  try {
396	    fn();
397	    console.log(`ok   ${name}`);
398	  } catch (e) {
399	    failed += 1;
400	    console.error(`FAIL ${name}\n     ${e.message}`);
401	  }
402	}
403	console.log(`${cases.length - failed}/${cases.length} passed`);
404	process.exit(failed ? 1 : 0);
